import { writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
// Check Import Cycles script supports OpenClaw repository automation.
import { readFileSync } from "node:fs";
import path from "node:path";
import ts from "file:///D:/ClawX/node_modules/.pnpm/typescript@5.9.3/node_modules/typescript/lib/typescript.js";
import { collectSourceFiles, collectStronglyConnectedComponents, formatCycle, } from "file:///C:/Users/27933/.codex/worktrees/architecture-convergence/ClawX/openclaw_runtime/scripts/lib/import-cycle-graph.ts";
const repoRoot = process.env.ARCHITECTURE_SCAN_ROOT;
const scanRoots = ["src", "extensions", "scripts"];
const sourceExtensions = [".ts", ".tsx", ".mts", ".cts", ".js", ".mjs", ".cjs"];
const testSourcePattern = /(?:\.test|\.e2e\.test)\.[cm]?[tj]sx?$/;
const generatedSourcePattern = /\.(?:generated|bundle)\.[tj]s$/;
const declarationSourcePattern = /\.d\.[cm]?ts$/;
const ignoredPathPartPattern = /(^|\/)(node_modules|dist|build|coverage|\.artifacts|\.git|assets)(\/|$)/;
function shouldSkipRepoPath(repoPath) {
    return (ignoredPathPartPattern.test(repoPath) ||
        testSourcePattern.test(repoPath) ||
        generatedSourcePattern.test(repoPath) ||
        declarationSourcePattern.test(repoPath));
}
function createSourceResolver(files) {
    const fileSet = new Set(files);
    const pathMap = new Map();
    for (const file of files) {
        const parsed = path.posix.parse(file);
        const extensionless = path.posix.join(parsed.dir, parsed.name);
        pathMap.set(extensionless, file);
        if (file.endsWith(".ts")) {
            pathMap.set(`${extensionless}.js`, file);
        }
        else if (file.endsWith(".tsx")) {
            pathMap.set(`${extensionless}.jsx`, file);
        }
        else if (file.endsWith(".mts")) {
            pathMap.set(`${extensionless}.mjs`, file);
        }
        else if (file.endsWith(".cts")) {
            pathMap.set(`${extensionless}.cjs`, file);
        }
    }
    return (importer, specifier) => {
        if (!specifier.startsWith(".")) {
            return null;
        }
        const base = path.posix.normalize(path.posix.join(path.posix.dirname(importer), specifier));
        const candidates = [
            base,
            ...sourceExtensions.map((extension) => `${base}${extension}`),
            `${base}/index.ts`,
            `${base}/index.tsx`,
            `${base}/index.js`,
            `${base}/index.mjs`,
        ];
        for (const candidate of candidates) {
            if (fileSet.has(candidate)) {
                return candidate;
            }
            const mapped = pathMap.get(candidate);
            if (mapped) {
                return mapped;
            }
        }
        return null;
    };
}
function importDeclarationHasRuntimeEdge(node) {
    if (!node.importClause) {
        return true;
    }
    if (node.importClause.isTypeOnly) {
        return false;
    }
    const bindings = node.importClause.namedBindings;
    if (node.importClause.name || !bindings || ts.isNamespaceImport(bindings)) {
        return true;
    }
    return bindings.elements.some((element) => !element.isTypeOnly);
}
function exportDeclarationHasRuntimeEdge(node) {
    if (!node.moduleSpecifier || node.isTypeOnly) {
        return false;
    }
    const clause = node.exportClause;
    if (!clause || ts.isNamespaceExport(clause)) {
        return true;
    }
    return clause.elements.some((element) => !element.isTypeOnly);
}
function collectRuntimeStaticImports(file, resolveSource) {
    const sourceFile = ts.createSourceFile(file, readFileSync(path.join(repoRoot, file), "utf8"), ts.ScriptTarget.Latest, true);
    const imports = [];
    const visit = (node) => {
        let specifier;
        let include = false;
        if (ts.isImportDeclaration(node) && ts.isStringLiteral(node.moduleSpecifier)) {
            specifier = node.moduleSpecifier.text;
            include = importDeclarationHasRuntimeEdge(node);
        }
        else if (ts.isExportDeclaration(node) &&
            node.moduleSpecifier &&
            ts.isStringLiteral(node.moduleSpecifier)) {
            specifier = node.moduleSpecifier.text;
            include = exportDeclarationHasRuntimeEdge(node);
        }
        if (include && specifier) {
            const resolved = resolveSource(file, specifier);
            if (resolved) {
                imports.push(resolved);
            }
        }
        ts.forEachChild(node, visit);
    };
    visit(sourceFile);
    return imports.toSorted((left, right) => left.localeCompare(right));
}
function main() {
    const files = scanRoots.flatMap((root) => collectSourceFiles(path.join(repoRoot, root), {
        repoRoot,
        sourceExtensions,
        shouldSkipRepoPath,
    }));
    const resolveSource = createSourceResolver(files);
    const graph = new Map(files.map((file) => [
        file,
        collectRuntimeStaticImports(file, resolveSource),
    ]));
    const components = collectStronglyConnectedComponents(graph);
    const sources = files.map(file => ({ file, sha256: createHash("sha256").update(readFileSync(path.join(repoRoot, file))).digest("hex") }));
    writeFileSync(process.env.ARCHITECTURE_SCAN_OUT, JSON.stringify({ driven_by: "agent", actor: "codex-architecture-convergence", scope: "Exact runtime checker graph with read-only output instrumentation", root: repoRoot, files: files.length, components, edges: [...graph], sourceHashes: sources }, null, 2) + "\n");
    console.log(`Import cycle check: ${components.length} runtime value cycle(s).`);
    if (components.length === 0) {
        return 0;
    }
    console.error("\nRuntime value import cycles:");
    for (const component of components) {
        console.error(`\n# component size ${component.length}`);
        console.error(formatCycle(component, graph));
    }
    console.error("\nBreak the cycle or convert type-only edges to `import type`.");
    return 1;
}
process.exitCode = main();
